/** Tab E managed Plotly 3D magnitude surface; numerical terrain is generated by the pure engine. */
import { useEffect, useRef, useState } from "react";
import { magnitudeLandscape, type TransferFunction } from "@/features/signals/engines/laplaceEngine";
import { loadPlotlyGl3d, type PlotlyRuntime } from "./plotlyRuntime";
export function LaplaceLandscape3D({ system }: { system: TransferFunction }) { const host = useRef<HTMLDivElement>(null); const [ready, setReady] = useState(false); useEffect(() => { let cancelled = false; let plotly: PlotlyRuntime | null = null; const root = host.current; if (!root) return; setReady(false); void loadPlotlyGl3d().then((runtime) => { if (cancelled || !host.current) return; plotly = runtime; const terrain = magnitudeLandscape(system, 40, 4, 14); return runtime.react(host.current, [{ type: "surface", x: terrain.x, y: terrain.y, z: terrain.z, colorscale: [[0, "#020617"], [.34, "#172554"], [.6, "#7c3aed"], [.82, "#ec4899"], [1, "#fbbf24"]], showscale: false, opacity: .96 }, { type: "scatter3d", mode: "lines", x: terrain.path.x, y: terrain.path.y, z: terrain.path.z.map((value) => value + .12), line: { color: "#fbbf24", width: 7 }, hoverinfo: "skip" }], { paper_bgcolor: "rgba(0,0,0,0)", margin: { l: 0, r: 0, b: 0, t: 6 }, scene: { bgcolor: "#07101e", xaxis: { title: { text: system.mode === "s" ? "σ" : "Re{z}" }, color: "#cbd5e1", gridcolor: "#334155" }, yaxis: { title: { text: system.mode === "s" ? "jω" : "Im{z}" }, color: "#cbd5e1", gridcolor: "#334155" }, zaxis: { title: { text: "|H| (clipped)" }, color: "#cbd5e1", gridcolor: "#334155", range: [0, 14] }, camera: { eye: { x: 1.45, y: 1.35, z: .92 } } } }, { displayModeBar: false, responsive: true, scrollZoom: true }); }).then(() => { if (!cancelled) setReady(true); }).catch(() => { if (!cancelled) setReady(false); }); return () => { cancelled = true; if (plotly && root) plotly.purge(root); }; }, [system]); return <div className="relative h-[440px] overflow-hidden rounded-2xl border border-violet-400/30 bg-[#07101e]"><div ref={host} className="h-full w-full" />{!ready && <div className="pointer-events-none absolute inset-0 grid place-items-center bg-[#07101e]"><span className="h-7 w-7 animate-spin rounded-full border-2 border-violet-300 border-t-transparent" /></div>}</div>; }
